const target = $now.startOf('week');
const targetWeek = target.toISODate();
const sourceWeek = target.minus({ days: 7 }).toISODate();
const watching = [
  'mushoku tensei jobless reincarnation',
  'chainsaw man',
  'jujutsu kaisen',
  'TSUKIMICHI -Moonlit Fantasy-'
];
const languages = {
  enabled: ['japanese', 'english'],
  patterns: { japanese: ['Japanese', '日本語'], english: ['English'] }
};
const isMonday = (value) => /^\d{4}-\d{2}-\d{2}$/.test(value) && new Date(`${value}T00:00:00Z`).getUTCDay() === 1;
if (!isMonday(targetWeek) || !isMonday(sourceWeek)) {
  throw new Error(`Invalid weekly range: ${sourceWeek} to ${targetWeek}`);
}
if (!Array.isArray(watching) || watching.some((title) => typeof title !== 'string' || !title.trim())) {
  throw new Error('Watching must be an array of non-empty title strings');
}
if (!Array.isArray(languages.enabled) || !languages.enabled.length || languages.enabled.some((name) => !Array.isArray(languages.patterns[name]) || !languages.patterns[name].length)) {
  throw new Error('Every enabled language needs at least one suffix pattern');
}
return [{ json: {
  target_week_start: targetWeek,
  source_week_start: sourceWeek,
  calendar_url: `https://www.crunchyroll.com/simulcastcalendar?filter=premium&date=${sourceWeek}`,
  watching,
  languages
} }];

const input = $json;
const config = $('Forecast Configuration').first().json;
const fields = ['titles', 'source_starts_at', 'urls', 'source_episodes'];
for (const field of fields) {
  if (!Array.isArray(input[field])) throw new Error(`HTML extraction did not return ${field}`);
}
const count = input.titles.length;
if (count < 1) throw new Error('Crunchyroll returned no release cards');
if (fields.some((field) => input[field].length !== count)) {
  throw new Error(`Release fields do not align: ${fields.map((field) => `${field}=${input[field].length}`).join(', ')}`);
}
const splitSuffix = (value) => {
  const clean = String(value).replace(/\s+/g, ' ').trim();
  if (!clean.endsWith(')')) return { title: clean, suffix: null };
  let depth = 0;
  for (let i = clean.length - 1; i >= 0; i--) {
    if (clean[i] === ')') depth++;
    if (clean[i] === '(') {
      depth--;
      if (depth === 0 && i > 0 && /\s/.test(clean[i - 1])) {
        return { title: clean.slice(0, i).trim(), suffix: clean.slice(i + 1, -1) };
      }
    }
  }
  return { title: clean, suffix: null };
};
const inferLanguage = (value) => {
  const parsed = splitSuffix(value);
  if (parsed.suffix === null) return { title: parsed.title, language: 'japanese' };
  const folded = parsed.suffix.toLocaleLowerCase('en-US');
  for (const [language, patterns] of Object.entries(config.languages.patterns)) {
    if (patterns.some((pattern) => pattern.toLocaleLowerCase('en-US') === folded)) {
      return { title: parsed.title, language };
    }
  }
  return { title: String(value).replace(/\s+/g, ' ').trim(), language: `other:${parsed.suffix}` };
};
const normalizeTitle = (value) => inferLanguage(value).title
  .replace(/\s+Season\s+\d+\b/gi, '')
  .replace(/\s+\d+(?:st|nd|rd|th)\s+Season\b/gi, '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, ' ')
  .trim();
const watched = new Set(config.watching.map(normalizeTitle));
const enabled = new Set(config.languages.enabled);
const releases = [];
const seen = new Set();
for (let index = 0; index < count; index++) {
  const parsed = inferLanguage(input.titles[index]);
  if (!enabled.has(parsed.language) || !watched.has(normalizeTitle(parsed.title))) continue;
  const sourceStart = new Date(input.source_starts_at[index]);
  const sourceEpisodeText = String(input.source_episodes[index] ?? '').trim();
  const sourceEpisode = /^\d+$/.test(sourceEpisodeText) ? Number(sourceEpisodeText) : null;
  const url = String(input.urls[index] ?? '').trim();
  if (Number.isNaN(sourceStart.getTime())) throw new Error(`Invalid release time for ${parsed.title}`);
  if (!url.startsWith('https://www.crunchyroll.com/')) throw new Error(`Invalid Crunchyroll URL for ${parsed.title}`);
  const release = {
    title: parsed.title,
    language: parsed.language,
    episode: sourceEpisode === null ? null : sourceEpisode + 1,
    starts_at: new Date(sourceStart.getTime() + 7 * 86400000).toISOString(),
    url,
    predicted: true,
    source_starts_at: sourceStart.toISOString(),
    source_episode: sourceEpisode
  };
  const key = [release.title, release.language, release.episode, release.starts_at, release.url].join('|');
  if (!seen.has(key)) {
    seen.add(key);
    releases.push(release);
  }
}
return [{ json: {
  contract_version: 1,
  week_start: config.target_week_start,
  source_week_start: config.source_week_start,
  predicted: true,
  languages: [...enabled].sort(),
  releases
} }];

const payload = $json;
if (payload.contract_version !== 1 || payload.predicted !== true || !Array.isArray(payload.releases)) {
  throw new Error('Invalid forecast contract');
}
return payload.releases.map((release) => ({
  json: {
    contract_version: payload.contract_version,
    week_start: payload.week_start,
    source_week_start: payload.source_week_start,
    ...release
  }
}));
